create table style_library (
  id bigint primary key auto_increment,
  external_id varchar(64) not null,
  name varchar(120) not null,
  category varchar(64) not null,
  description text not null,
  source_image_url varchar(1000) not null,
  storage_path varchar(1000) not null,
  image_url varchar(1000) not null,
  image_width int null,
  image_height int null,
  is_public boolean not null,
  sort_order int not null,
  created_at datetime not null,
  updated_at datetime not null,
  unique key uk_style_library_external_id (external_id),
  index idx_style_library_public_category_sort (is_public, category, sort_order),
  index idx_style_library_public_sort (is_public, sort_order)
);

