insert into style_library
  (external_id, name, category, description, source_image_url, storage_path, image_url, image_width, image_height, is_public, sort_order, created_at, updated_at)
values
  ('864621266010645040', '3D风格-高清真实渲染', '3D风格', '高清 3D 真实渲染风格，8K 级高精度几何与 8K PBR 纹理，路径追踪全局光照与精准反射折射，高细节位移贴图与毛发系统，照片级皮肤次表面散射与毛孔级细节，超写实数字渲染的极致真实感与影院级画面品质。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baf4d4af6176826adf4fc.png', 'style-library/public/864621266010645040/cover.png', '/api/style-library/images/864621266010645040', 2048, 1152, true, 1, now(), now()),
  ('864621148205228583', '3D风格-西方卡通', '3D风格', '3D 西方卡通风格，欧美动画式圆润夸张造型与饱满体块，柔和卡通着色与明亮高饱和色彩，细腻表情与动态张力，温暖电影级光照与景深，西方动画工作室的角色设计辨识度与亲和力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baf314af6176826adf4f9.png', 'style-library/public/864621148205228583/cover.png', '/api/style-library/images/864621148205228583', 2048, 1152, true, 2, now(), now()),
  ('864621071868892871', '3D风格-定格动画', '3D风格', '定格动画风格 3D 渲染，手工材料质感如毛毡纸板与木质，微缩布景与关节可动人偶，浅景深移轴摄影感与温暖实用光源，帧间微抖动的手工动画韵律，莱卡工作室式的逐帧动画质朴温度与叙事魅力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baf1fc634da38976e381d.png', 'style-library/public/864621071868892871/cover.png', '/api/style-library/images/864621071868892871', 2048, 1152, true, 3, now(), now()),
  ('864620994798559765', '3D风格-果冻状塑料', '3D风格', '3D 果冻状塑料风格渲染，半透明次表面散射与柔软弹性质感，高饱和糖果色与内部气泡细节，柔和环境光折射与边缘透光，圆润 Q 弹造型，清新甜美的果冻玩具视觉趣味。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baf0d4af6176826adf4f6.png', 'style-library/public/864620994798559765/cover.png', '/api/style-library/images/864620994798559765', 2048, 1152, true, 4, now(), now()),
  ('864620913097709239', '3D风格-光泽乳胶渲染', '3D风格', '3D 光泽乳胶渲染风格，高反射光滑乳胶表面与镜面高光，紧身流线型造型与柔韧材质褶皱，冷调环境光与锐利定向高光，暗调背景突出质感反光，时尚前卫的光泽材质视觉冲击力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baef9c634da38976e3815.png', 'style-library/public/864620913097709239/cover.png', '/api/style-library/images/864620913097709239', 2048, 1152, true, 5, now(), now()),
  ('864620842310443528', '3D风格-中国奇幻动画', '3D风格', '3D 中国奇幻动画风格，水墨贴图与琉璃质感材质融合，飞檐仙阁与山水云雾场景，飘逸衣袂布料模拟与法术粒子特效，青绿金碧配色与体积丁达尔光，东方仙侠动画的瑰丽壮美与仙气飘逸。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baee84af6176826adf4f0.png', 'style-library/public/864620842310443528/cover.png', '/api/style-library/images/864620842310443528', 2048, 1152, true, 6, now(), now()),
  ('864620759850426877', '3D风格-加强版卡通渲染', '3D风格', '3D 加强版卡通渲染，精细赛璐璐色阶分层与高光反射，描边轮廓与 rim 光增强，风格化法线细节与手绘贴图质感，高饱和色彩与柔和环境光遮蔽，比传统三渲二更精致丰富的卡通 3D 画面表现力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baed54af6176826adf4ed.png', 'style-library/public/864620759850426877/cover.png', '/api/style-library/images/864620759850426877', 2048, 1152, true, 7, now(), now()),
  ('864620677684008614', '3D风格-粘土动画', '3D风格', '粘土动画定格风格 3D 渲染，黏土柔软质感与指纹压痕细节，哑光不均匀表面色彩与手工捏塑痕迹，柔和定向光照与浅景深微缩感，阿德曼工作室式的手工质朴与温暖童趣。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baec1c634da38976e3814.png', 'style-library/public/864620677684008614/cover.png', '/api/style-library/images/864620677684008614', 2048, 1152, true, 8, now(), now()),
  ('864620600332654242', '3D风格-魔幻角色扮演', '3D风格', '3D 魔幻角色扮演游戏美术，暗黑奇幻厚涂风格贴图与金属铠甲 PBR 材质，史诗场景大气透视与体积光效，角色装备高细节雕刻与魔法粒子特效，中世纪魔幻世界的厚重感与冒险史诗氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baeafc634da38976e3812.png', 'style-library/public/864620600332654242/cover.png', '/api/style-library/images/864620600332654242', 2048, 1152, true, 9, now(), now()),
  ('864620434527625681', '3D风格-复古Y2K奇幻', '3D风格', 'Y2K 复古奇幻 3D 风格，2000 年代早期 3D 渲染质感与低分辨率贴图，金属铬合金与半透明塑料材质，赛博与精灵混搭的奇幻造型，鲜艳荧光色与早期光照引擎的扁平阴影，千禧年数字美学与魔幻想象力的怀旧碰撞。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae874af6176826adf4e5.png', 'style-library/public/864620434527625681/cover.png', '/api/style-library/images/864620434527625681', 2048, 1152, true, 10, now(), now()),
  ('864620325320529448', '3D风格-卡通动画', '3D风格', '3D 卡通动画风格，圆润流畅角色造型与夸张动态姿势，柔和 Toon 渲染与明亮色块，活泼表情与肢体张力，温暖叙事光照与浅景深散景，现代 3D 动画剧集的轻快质感与角色感染力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae6dc634da38976e3727.png', 'style-library/public/864620325320529448/cover.png', '/api/style-library/images/864620325320529448', 2048, 1152, true, 11, now(), now()),
  ('864620237206590483', '3D风格-简约卡通风', '3D风格', '3D 简约卡通人物，低多边形圆润造型与极简面部特征，柔和均匀光照无复杂阴影，高饱和纯色材质与光滑表面，可爱亲和的角色设计，适合品牌 IP 与移动端应用的清爽 3D 人设。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae58c634da38976e3702.png', 'style-library/public/864620237206590483/cover.png', '/api/style-library/images/864620237206590483', 2048, 1152, true, 12, now(), now()),
  ('864620109393564685', '3D风格-游戏渲染', '3D风格', '3D 游戏渲染风格，实时渲染优化光照与烘焙 AO，风格化 PBR 材质与法线细节，动态色调映射与后期泛光，游戏级 LOD 几何与特效粒子，AAA 游戏过场动画的视觉冲击力与沉浸感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae39c634da38976e36fc.png', 'style-library/public/864620109393564685/cover.png', '/api/style-library/images/864620109393564685', 2048, 1152, true, 13, now(), now()),
  ('864620012391899571', '3D风格-真实感PBR渲染', '3D风格', '3D 真实感 PBR 渲染，基于物理的材质系统与真实粗糙度金属度参数，HDRI 环境光照与光线追踪反射，高细节法线与位移贴图，照片级真实质感还原，工业级产品可视化的精确材质表现。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae224af6176826adf4dd.png', 'style-library/public/864620012391899571/cover.png', '/api/style-library/images/864620012391899571', 2048, 1152, true, 14, now(), now()),
  ('864619879512154526', '3D风格-厚涂风格', '3D风格', '3D 厚涂风格渲染，油画笔触感法线贴图与颜料堆叠质感，高对比明暗与局部暖光穿透，粗糙肌理表面与厚重色彩层次，介于数字雕塑与概念绘画之间的艺术化 3D 表现力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bae034af6176826adf4d4.png', 'style-library/public/864619879512154526/cover.png', '/api/style-library/images/864619879512154526', 2048, 1152, true, 15, now(), now()),
  ('864619790173475819', '3D风格-美国卡通渲染', '3D风格', '美式卡通 3D 渲染，皮克斯式饱满圆润造型与细腻次表面散射，温暖柔和全局光照与电影级景深，高质感织物与毛发模拟，角色表情生动夸张，好莱坞动画工作室级精品质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4badedc634da38976e36f5.png', 'style-library/public/864619790173475819/cover.png', '/api/style-library/images/864619790173475819', 2048, 1152, true, 16, now(), now()),
  ('864619689946387426', '3D风格-卡通渲染', '3D风格', '3D 卡通渲染风格，赛璐璐 Toon 着色器硬边色阶分层，简洁双色调光影与清晰描边，高饱和明亮色彩与光滑材质，圆润造型与夸张表情，清爽干净的现代卡通 3D 视觉。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4badd5c634da38976e36f4.png', 'style-library/public/864619689946387426/cover.png', '/api/style-library/images/864619689946387426', 2048, 1152, true, 17, now(), now()),
  ('864619595754902492', '3D风格-国风3D高清渲染', '3D风格', '国风 3D 高清渲染，传统纹样贴图与琉璃玉质 PBR 材质，仙阁楼台与山水场景建模，金线勾边与青绿配色，体积丁达尔光与粒子特效，东方仙侠游戏的高品质美术质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4badbfc634da38976e36f2.png', 'style-library/public/864619595754902492/cover.png', '/api/style-library/images/864619595754902492', 2048, 1152, true, 18, now(), now()),
  ('864619513303274453', '3D风格-UE5写实渲染', '3D风格', 'UE5 虚幻引擎写实渲染，Lumen 全局光照与 Nanite 高精度几何，路径追踪级光线追踪反射与折射，真实物理材质与大气体积雾，次表面散射与毛发渲染，照片级真实感与电影级后期色彩分级。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4badabc634da38976e36f0.png', 'style-library/public/864619513303274453/cover.png', '/api/style-library/images/864619513303274453', 2048, 1152, true, 19, now(), now()),
  ('864619428238598511', '3D风格-超现实3D渲染', '3D风格', '超现实 3D 渲染风格，物理悖论的空间构图与悬浮错位物体，无限镜面反射与非线性透视，冷冽超现实色彩与不真实光源，高精度 PBR 材质渲染梦境场景，达利式潜意识视觉的 3D 数字化重构。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad974af6176826adf4ca.png', 'style-library/public/864619428238598511/cover.png', '/api/style-library/images/864619428238598511', 2048, 1152, true, 20, now(), now()),
  ('864619351461860295', '3D风格-动漫三渲二', '3D风格', '3D 三渲二动画风格，赛璐璐色阶 Toon 着色与精简光影分层，清晰描边轮廓与扁平色块，日系动画角色比例与表情，柔和rim光与背景虚化，2D 动画质感与 3D 空间纵深融合。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad85c634da38976e36e8.png', 'style-library/public/864619351461860295/cover.png', '/api/style-library/images/864619351461860295', 2048, 1152, true, 21, now(), now()),
  ('864619252539200414', '3D风格-盲盒涂装风', '3D风格', '3D 盲盒公仔涂装风格，Q 版大头小身比例与圆润光洁表面，高饱和哑光涂装与水贴移印细节，柔和均匀布光无强烈阴影，微缩手办底座与配件，潮玩收藏的精致可爱质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad6dc634da38976e36d9.png', 'style-library/public/864619252539200414/cover.png', '/api/style-library/images/864619252539200414', 2048, 1152, true, 22, now(), now()),
  ('864619177486328115', '3D风格-美式卡通游戏', '3D风格', '3D 美式卡通游戏美术，暴雪式粗轮廓与夸张体块造型，高饱和色块贴图与硬边卡通描边，动态光照与特效粒子，圆润金属与皮革手绘质感，美式卡通游戏的鲜明视觉冲击力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad5b4af6176826adf4b6.png', 'style-library/public/864619177486328115/cover.png', '/api/style-library/images/864619177486328115', 2048, 1152, true, 23, now(), now()),
  ('864619093268898095', '3D风格-国风高清渲染', '3D风格', '3D 国风高清渲染，工笔重彩与水墨晕染贴图质感，祥云瑞兽与飞檐斗拱建模，金碧辉煌与青绿山水色调，体积光穿透仙雾的次表面散射，东方仙侠世界的瑰丽与庄严。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad474af6176826adf4b3.png', 'style-library/public/864619093268898095/cover.png', '/api/style-library/images/864619093268898095', 2048, 1152, true, 24, now(), now()),
  ('864619006601994536', '3D风格-数字雕刻', '3D风格', '3D 数字雕刻风格，ZBrush 雕刻笔触质感与高细节浮雕纹样，黏土般湿润表面与刮刀痕迹，高密度几何细节与法线凹凸，单侧硬光突出体积转折，雕塑工作室的原始粗犷力量感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad334af6176826adf4b0.png', 'style-library/public/864619006601994536/cover.png', '/api/style-library/images/864619006601994536', 2048, 1152, true, 25, now(), now()),
  ('864618918815208324', '3D风格-欧美风格化', '3D风格', '欧美风格化 3D 渲染，粗犷有力的造型轮廓与体块化光影，手绘纹理贴图与笔触感着色，高对比色彩与戏剧布光，梦工厂式角色夸张比例与表情张力，兼具卡通趣味与电影级氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad1ec634da38976e36c9.png', 'style-library/public/864618918815208324/cover.png', '/api/style-library/images/864618918815208324', 2048, 1152, true, 26, now(), now()),
  ('864618827475850110', '3D风格-卡通微缩景观', '3D风格', '3D 卡通微缩景观，移轴摄影般的浅景深微缩感，圆润可爱的小比例造型与柔和材质，精致迷你场景道具细节，温暖明亮光照与柔和阴影，童话书般的袖珍世界奇观感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bad08c634da38976e36c2.png', 'style-library/public/864618827475850110/cover.png', '/api/style-library/images/864618827475850110', 2048, 1152, true, 27, now(), now()),
  ('864618734035149077', '3D风格-风格化渲染', '3D风格', '3D 风格化渲染，非写实手绘感着色与色块化光影，柔和环境光遮蔽与卡通轮廓光，略带夸张的造型比例，明快饱和色彩与简洁材质表达，介于写实与卡通之间的艺术化 3D 视觉语言。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bacf24af6176826adf4a0.png', 'style-library/public/864618734035149077/cover.png', '/api/style-library/images/864618734035149077', 2048, 1152, true, 28, now(), now()),
  ('864618653248659725', '3D风格-高品质动画渲染', '3D风格', '3D 高品质动画渲染，次表面散射皮肤质感与全局光照，精致毛发与布料物理模拟，影院级光线追踪与体积光效，高细节 PBR 材质，皮克斯级动画电影的精品质感与温暖叙事氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bacde4af6176826adf49e.png', 'style-library/public/864618653248659725/cover.png', '/api/style-library/images/864618653248659725', 2048, 1152, true, 29, now(), now()),
  ('864618528539418879', '2D风格-像素风', '2D风格', '像素艺术插画风格，8/16 位有限色板的像素色块构成，锯齿边缘与网格化造型，复古电子游戏的点阵质感，逐像素精绘的细节与动画帧感，怀旧电子美学。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bacc14af6176826adf49a.png', 'style-library/public/864618528539418879/cover.png', '/api/style-library/images/864618528539418879', 2048, 1152, true, 30, now(), now()),
  ('864618419483317073', '2D风格-东方水墨风', '2D风格', '东方水墨写意插画，毛笔枯润浓淡变化与泼墨渲染，留白意境与诗意构图，淡彩点缀的水墨晕染层次，宣纸与绢本纹理质感，东方哲学的空灵淡远与文人画气韵。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baca7c634da38976e36b9.png', 'style-library/public/864618419483317073/cover.png', '/api/style-library/images/864618419483317073', 2048, 1152, true, 31, now(), now()),
  ('864618301598208803', '2D风格-暗色调哥特', '2D风格', '复古哥特插画风格，半色调网点纹理与暗色调印刷质感，维多利亚装饰花纹与哥特尖拱元素，深紫黑与暗红的阴郁配色，老式印刷的套色偏差与颗粒感，维多利亚哥特的颓废神秘。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bac8ac634da38976e36b3.png', 'style-library/public/864618301598208803/cover.png', '/api/style-library/images/864618301598208803', 2048, 1152, true, 32, now(), now()),
  ('864618110673494179', '2D风格-简洁插画', '2D风格', '极简插画风格，几何化抽象造型与有限调色板，大面积留白与负空间运用，去除细节的纯粹线条与色块，现代设计的克制与优雅，信息传达精准的视觉简约美学。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bac5d4af6176826adf48d.png', 'style-library/public/864618110673494179/cover.png', '/api/style-library/images/864618110673494179', 2048, 1152, true, 33, now(), now()),
  ('864618018289754268', '2D风格-暗黑漫画', '2D风格', '暗黑系漫画插画风格，粗犷凌厉的 ink 线条与大面积黑色填充，高对比黑白无灰阶过渡，暴力美学与身体异化造型，压抑窒息的画面氛围，极致黑暗的视觉冲击力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bac474af6176826adf48b.png', 'style-library/public/864618018289754268/cover.png', '/api/style-library/images/864618018289754268', 2048, 1152, true, 34, now(), now()),
  ('864617926694543505', '2D风格-黑暗奇幻', '2D风格', '黑暗奇幻插画风格，冷灰蓝与暗紫色调主导，魔法光效与怪物设计，厚涂暗调氛围与精细装备刻画，史诗级奇幻世界的危险与神秘感，龙与地下城式的暗黑冒险美学。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bac314af6176826adf487.png', 'style-library/public/864617926694543505/cover.png', '/api/style-library/images/864617926694543505', 2048, 1152, true, 35, now(), now()),
  ('864617841151713423', '2D风格-美式复古哥特', '2D风格', '美式复古哥特插画风格，精细繁复的钢笔线条与交叉排线阴影，复古童话与幽默趣味并存，低饱和度的灰褐墨绿色调，夸张修长的角色造型与独特比例，尖顶建筑与修长剪影的复古哥特美学。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bac1d4af6176826adf484.png', 'style-library/public/864617841151713423/cover.png', '/api/style-library/images/864617841151713423', 2048, 1152, true, 36, now(), now()),
  ('864617657554440860', '2D风格-皮影戏', '2D风格', '中国皮影戏风格插画，镂空剪影造型与关节连接结构，半透明牛皮材质质感，暖色光源从背后透射形成轮廓光效，装饰性纹样雕刻细节，民间艺术的古朴与光影戏剧感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4babf1c634da38976e36a2.png', 'style-library/public/864617657554440860/cover.png', '/api/style-library/images/864617657554440860', 2048, 1152, true, 37, now(), now()),
  ('864617563866272406', '2D风格-黑暗原画概念', '2D风格', '暗黑原画概念艺术，低明度高对比的阴郁色调，哥特建筑与废墟环境，精细厚涂的光影层次，恐怖怪物与腐朽质感设计，压抑绝望的黑暗奇幻世界观。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4babdbc634da38976e36a1.png', 'style-library/public/864617563866272406/cover.png', '/api/style-library/images/864617563866272406', 2048, 1152, true, 38, now(), now()),
  ('864617445339439211', '2D风格-卡通插画', '2D风格', '2D 卡通插画风格，简约几何化造型与明亮饱和色彩，平面化设计无复杂光影，圆润流畅的线条与大色块填充，轻松活泼的现代扁平插画质感，适合 UI 与品牌视觉的清爽风格。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4babbe4af6176826adf480.png', 'style-library/public/864617445339439211/cover.png', '/api/style-library/images/864617445339439211', 2048, 1152, true, 39, now(), now()),
  ('864617344160240259', '2D风格-中国神话', '2D风格', '中国神话题材插画，工笔重彩与水墨写意融合，祥云瑞兽与仙山楼阁意象，金碧辉煌与青绿山水色调，飘逸流畅的衣袂线条与装饰性纹样，仙气弥漫的东方神话史诗感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baba6c634da38976e3698.png', 'style-library/public/864617344160240259/cover.png', '/api/style-library/images/864617344160240259', 2048, 1152, true, 40, now(), now()),
  ('864617242406428764', '2D风格-上美画风', '2D风格', '上海美术电影制片厂动画风格，中国传统装饰性线条与民族色彩，水墨晕染与工笔重彩结合，造型取材民间艺术与戏曲脸谱，意境悠远的东方动画美学，经典国产动画的民族化视觉语言。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bab8e4af6176826adf479.png', 'style-library/public/864617242406428764/cover.png', '/api/style-library/images/864617242406428764', 2048, 1152, true, 41, now(), now()),
  ('864617114148803178', '2D风格-手冢治虫时代', '2D风格', '手冢治虫时代复古卡通画风，圆润简约的流畅线条，大头小身体的可爱比例，温暖柔和的复古色调，表情丰富生动，昭和时代动画的纯真与温暖怀旧质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bab6fc634da38976e3692.png', 'style-library/public/864617114148803178/cover.png', '/api/style-library/images/864617114148803178', 2048, 1152, true, 42, now(), now()),
  ('864616998167908946', '2D风格-暗色调厚涂', '2D风格', '暗色调厚涂插画，油画质感厚重笔触与颜料堆叠感，低明度高对比的暗色基调，局部暖光穿透黑暗，丰富的肌理与层次，沉稳厚重的氛围与情绪张力。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bab54c634da38976e368d.png', 'style-library/public/864616998167908946/cover.png', '/api/style-library/images/864616998167908946', 2048, 1152, true, 43, now(), now()),
  ('864616888713355323', '2D风格-大友克洋风格', '2D风格', '大友克洋风格插画，精细写实的机械与建筑描绘，废墟文明的末世沉静，灰蓝与土黄色调，细腻钢笔排线与灰阶渐变，宏大的城市崩塌构图，冷静克制中暗含毁灭的力量。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bab3a4af6176826adf473.png', 'style-library/public/864616888713355323/cover.png', '/api/style-library/images/864616888713355323', 2048, 1152, true, 44, now(), now()),
  ('864616731292739471', '2D风格-热血漫画', '2D风格', '高质量 2D 热血少年漫画风格，粗犷有力的动态线条与速度线，高对比黑白与局部高饱和色彩点缀，夸张透视与冲击力构图，笔触充满力量感与运动张力，热血激昂的战斗氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4bab144af6176826adf46f.png', 'style-library/public/864616731292739471/cover.png', '/api/style-library/images/864616731292739471', 2048, 1152, true, 45, now(), now()),
  ('864616637747171893', '2D风格-黑白漫画', '2D风格', '黑白二维漫画动画风格，清晰 ink 线稿与网点纸阴影，日式分镜构图与集中线效果，高对比黑白灰阶，动态速度线与拟声词排版，经典日式黑白漫画的叙事节奏感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baafec634da38976e3680.png', 'style-library/public/864616637747171893/cover.png', '/api/style-library/images/864616637747171893', 2048, 1152, true, 46, now(), now()),
  ('864616426433942049', '2D风格-儿童蜡笔手绘', '2D风格', '儿童蜡笔手绘插画，蜡笔涂抹的粗糙颗粒质感与不规则边缘，鲜艳纯色叠加，稚拙天真的造型与歪斜线条，童趣率真的画面表达，温暖纯朴的手作温度。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baacbc634da38976e367a.png', 'style-library/public/864616426433942049/cover.png', '/api/style-library/images/864616426433942049', 2048, 1152, true, 47, now(), now()),
  ('864616259009909253', '2D风格-复古迷幻', '2D风格', '60-70 年代迷幻海报插画风格，流动扭曲的有机线条与漩涡构图，高饱和荧光色与互补色碰撞，纸质印刷肌理与套色错位效果，迷幻摇滚视觉的眩晕与超现实氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baaa3c634da38976e3672.png', 'style-library/public/864616259009909253/cover.png', '/api/style-library/images/864616259009909253', 2048, 1152, true, 48, now(), now()),
  ('864616132635535191', '2D风格-美式漫画插画', '2D风格', '美式漫画插画风格，粗黑墨线勾勒与高饱和色块填充，动态夸张透视与冲击力构图，交叉排线阴影刻画，明快强烈的色彩对比，超级英雄漫画的经典视觉语言。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baa854af6176826adf459.png', 'style-library/public/864616132635535191/cover.png', '/api/style-library/images/864616132635535191', 2048, 1152, true, 49, now(), now()),
  ('864615897473487338', '2D风格-黑白水墨风', '2D风格', '传统黑白水墨插画，毛笔浓淡干湿变化与飞白笔触，墨分五色的层次过渡，大量留白构图与意境表达，宣纸纹理质感，东方写意精神的简约与空灵。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baa4dc634da38976e3667.png', 'style-library/public/864615897473487338/cover.png', '/api/style-library/images/864615897473487338', 2048, 1152, true, 50, now(), now()),
  ('864615795371545062', '2D风格-达利风格', '2D风格', '达利超现实主义插画，融化的时钟与荒诞梦境意象，精细古典油画笔触与写实技法，空旷地平线与拉长变形的形体，暖黄沙漠色调与冷蓝天空对比，潜意识世界的诡谲静谧。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baa35c634da38976e3661.png', 'style-library/public/864615795371545062/cover.png', '/api/style-library/images/864615795371545062', 2048, 1152, true, 51, now(), now()),
  ('864615700601246178', '2D风格-国漫二次元常用', '2D风格', '国漫二次元插画风格，介于日系赛璐璐与中国风之间，鲜明饱和色彩与国潮元素装饰，角色造型偏写实比例，动态构图与特效光影，兼具东方审美与现代动画制作质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4baa1ec634da38976e365e.png', 'style-library/public/864615700601246178/cover.png', '/api/style-library/images/864615700601246178', 2048, 1152, true, 52, now(), now()),
  ('864615531486908880', '2D风格-游戏概念艺术', '2D风格', '游戏概念艺术插画，数字厚涂技法，环境氛围设计与史诗场景构图，丰富光影层次与大气雾效，高完成度细节刻画，奇幻与科幻融合的 AAA 级游戏美术质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba9f6c634da38976e3656.png', 'style-library/public/864615531486908880/cover.png', '/api/style-library/images/864615531486908880', 2048, 1152, true, 53, now(), now()),
  ('864615428848101142', '2D风格-赛博朋克数字', '2D风格', '赛博朋克数字插画，霓虹品红与青蓝高对比色彩，机械义体与人体融合设计，全息界面与电路纹理细节，雨夜城市背景，高饱和暗调，未来反乌托邦的科技疏离感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba9de4af6176826adf442.png', 'style-library/public/864615428848101142/cover.png', '/api/style-library/images/864615428848101142', 2048, 1152, true, 54, now(), now()),
  ('864615247922598327', '2D风格-插画蒸汽波', '2D风格', '蒸汽波美学数字插画，80 年代复古未来主义，粉紫与青蓝渐变色调，网格地平线与棕榈树剪影，古典雕塑与早期 Windows UI 元素拼贴，磁带失真与扫描线质感，迷幻怀旧数字梦境。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba9b2c634da38976e3651.png', 'style-library/public/864615247922598327/cover.png', '/api/style-library/images/864615247922598327', 2048, 1152, true, 55, now(), now()),
  ('864615167714922920', '2D风格-日系平涂插画', '2D风格', '日系赛璐璐平涂插画，干净均匀色块无笔触痕迹，柔和渐变过渡，清爽透明的高明度色调，细腻线稿与精致眼部刻画，轻快治愈的少女系插画质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba99fc634da38976e364d.png', 'style-library/public/864615167714922920/cover.png', '/api/style-library/images/864615167714922920', 2048, 1152, true, 56, now(), now()),
  ('864615046017192348', '2D风格-美国游戏概念', '2D风格', '美式游戏概念艺术插画，厚涂写实光影与高细节刻画，史诗奇幻世界观，油画质感笔触融合数字绘画，戏剧性布光与大气透视，好莱坞级场景概念设计语言。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba982c634da38976e3645.png', 'style-library/public/864615046017192348/cover.png', '/api/style-library/images/864615046017192348', 2048, 1152, true, 57, now(), now()),
  ('864614865133643490', '2D风格-二次元概念艺术', '2D风格', '2D 二次元概念艺术插画，赛璐璐平涂与厚涂光影结合，丰富饱和色彩与世界观设定感，精细场景设计与角色立绘，日系动画美术风格，干净色块与柔和渐变并存的画面质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba9574af6176826adf430.png', 'style-library/public/864614865133643490/cover.png', '/api/style-library/images/864614865133643490', 2048, 1152, true, 58, now(), now()),
