  ('864610849007871261', '真人风格-韩剧都市', '真人风格', '韩剧都市柔光真人摄影，奶油白与暖灰色调，柔焦磨皮肤质，城市夜景霓虹散景，浅景深人像，温暖治愈又略带感伤的情绪氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba59a4af6176826adf3b4.png', 'style-library/public/864610849007871261/cover.png', '/api/style-library/images/864610849007871261', 2048, 1152, true, 87, now(), now()),
  ('864610720578278783', '真人风格-日式生活', '真人风格', '日式生活自然光真人摄影，低饱和暖灰与木色基调，窗光柔和漫射，原木纹理与和纸质感，安静克制的日常构图，侘寂美学的平淡温度。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba57bc634da38976e3488.png', 'style-library/public/864610720578278783/cover.png', '/api/style-library/images/864610720578278783', 2048, 1152, true, 88, now(), now()),
  ('864610586897421677', '真人风格-日式胶片', '真人风格', '日系青春胶片真人摄影，柔和过曝的青绿与暖黄色调，逆光眩光与镜头光斑， Portra 胶片颗粒质感，清新淡雅略带褪色感，蝉鸣与校服的夏日怀旧氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba55bc634da38976e3481.png', 'style-library/public/864610586897421677/cover.png', '/api/style-library/images/864610586897421677', 2048, 1152, true, 89, now(), now()),
  ('864610382685152494', '真人风格-古偶唯美柔光', '真人风格', '古偶唯美柔光真人摄影，柔粉玫瑰石英与象牙白暖调，金色逆光勾勒丝发纱衣轮廓，瓷器肌肤光泽与水润唇眸高光，柔焦滤镜光晕，85mm大光圈奶油散景，花瓣金粉飘浮的浪漫诗意。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba52a4af6176826adf3a6.png', 'style-library/public/864610382685152494/cover.png', '/api/style-library/images/864610382685152494', 2048, 1152, true, 90, now(), now()),
  ('864610281795364070', '真人风格-国产悬疑冷调', '真人风格', '国产悬疑冷调真人摄影，极度去饱和的石板灰与病态青绿，荧光灯惨白微闪光源，潮湿水雾弥漫，手持纪实晃动感，暗部压暗提亮带雾，都市孤独与隐藏真相的不安。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba5124af6176826adf3a3.png', 'style-library/public/864610281795364070/cover.png', '/api/style-library/images/864610281795364070', 2048, 1152, true, 91, now(), now()),
  ('864610092619670747', '真人风格-宫斗权谋冷峻', '真人风格', '古代宫廷深色调真人摄影，深红墨黑为主点缀陈年金与冷钢蓝，单侧硬光低调明暗对照，对称压迫构图，丝绸玉器铜器包浆质感，肤色调冷白，权力博弈的窒息感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba4e54af6176826adf39f.png', 'style-library/public/864610092619670747/cover.png', '/api/style-library/images/864610092619670747', 2048, 1152, true, 92, now(), now()),
  ('864609832107254987', '真人风格-复古朋克', '真人风格', '1950年代复古未来主义真人摄影，铬合金与原子能美学，薄荷绿、奶油白与焦橙色调，温暖白炽灯搭配冷蓝边缘光，柯达彩色胶片颗粒与高光晕染，世纪中叶现代设计语言。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba4a74af6176826adf395.png', 'style-library/public/864609832107254987/cover.png', '/api/style-library/images/864609832107254987', 2048, 1152, true, 93, now(), now()),
  ('827924895316452400', '漫画风格-都市', '漫画风格', '都市画风，现代都市漫画风，线条流畅细腻，色彩质感高级，光影立体且有通透感，刻画偏向写实向动漫风格，粗犷而富有表现力的手绘线稿，关键轮廓线使用粗黑线强调。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6a4ba3db4af6176826adf37c.png', 'style-library/public/827924895316452400/cover.png', '/api/style-library/images/827924895316452400', 759, 411, true, 94, now(), now()),
  ('826516750463512787', '日本漫画风格', '未分组', '正宗日本漫画风格，赛璐璐涂色，干净细腻的线稿，清晰的动漫光影，鲜艳的动漫调色，2D插画，二次元杰作。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c10fd54af656473b8cb4c5.jpg', 'style-library/public/826516750463512787/cover.jpg', '/api/style-library/images/826516750463512787', 2752, 1536, true, 95, now(), now()),
  ('826516699217503997', '韩国条漫风格', '未分组', '韩国条漫美学，平滑的数字绘画，柔和发光的高光，丰富的色彩过渡，高对比度光影，高级韩漫画风，光泽感渲染。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c10fed4af656473b8cb4ce.jpg', 'style-library/public/826516699217503997/cover.jpg', '/api/style-library/images/826516699217503997', 2752, 1536, true, 96, now(), now()),
  ('826516651423412427', '2D平涂风格', '未分组', '2D平涂着色，干净的矢量图风格，极简色彩渲染，粗犷的轮廓线，鲜艳的纯色，清晰的色彩边界，无渐变，扁平化插画。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c110204af656473b8cb4d2.jpg', 'style-library/public/826516651423412427/cover.jpg', '/api/style-library/images/826516651423412427', 2752, 1536, true, 97, now(), now()),
  ('826516602308112581', '3D动漫风格', '未分组', '3D动漫风格，三维渲染，虚幻引擎5渲染，辛烷渲染器，平滑的网格纹理，柔和的3D边缘光，VTB虚拟主播美学，高清3D。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c110514af656473b8cb4da.jpg', 'style-library/public/826516602308112581/cover.jpg', '/api/style-library/images/826516602308112581', 2752, 1536, true, 98, now(), now()),
