  ('826516430261954264', '甜美少女风格', '未分组', '少女漫画风格，梦幻浪漫的氛围，柔和的粉色与马卡龙色调，柔和闪烁的光芒，抽象花卉背景图案，空灵的光影。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1110fcad46a443b2b079b.jpg', 'style-library/public/826516430261954264/cover.jpg', '/api/style-library/images/826516430261954264', 2752, 1536, true, 102, now(), now()),
