  ('826516138493587571', '古典写意风格', '未分组', '古典写意插画，松弛且富有表现力的笔触，充满诗意的氛围，柔和的复古色彩，流畅的水墨晕染，艺术表现主义。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c111764af656473b8cb510.jpg', 'style-library/public/826516138493587571/cover.jpg', '/api/style-library/images/826516138493587571', 2752, 1536, true, 106, now(), now()),
