  ('826516054485872699', '萌系风格', '未分组', '萌系动漫风格，超柔和阴影，闪亮圆润的高光，柔和甜美的调色，毛绒绒的质感，温柔可爱的视觉表现。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c111a24af656473b8cb519.jpg', 'style-library/public/826516054485872699/cover.jpg', '/api/style-library/images/826516054485872699', 2752, 1536, true, 108, now(), now()),
  ('826516019383742481', '洛丽塔风格', '未分组', '洛丽塔时尚美学，复杂的抽象蕾丝图案，华丽的装饰性边框，洛可可粉彩色调，优雅可爱，柔和发光，丰富的褶皱质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c111ed4af656473b8cb520.jpg', 'style-library/public/826516019383742481/cover.jpg', '/api/style-library/images/826516019383742481', 2752, 1536, true, 109, now(), now()),
  ('826515977688166411', '学院漫画风格', '未分组', '动漫学院美学，整洁严谨的线稿，菱形格纹图案元素，青春明亮的电影级调色，午后阳光穿透，干净整洁的构图。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c11212cad46a443b2b07c7.jpg', 'style-library/public/826515977688166411/cover.jpg', '/api/style-library/images/826515977688166411', 2752, 1536, true, 110, now(), now()),
  ('826515925972398083', '国漫唯美风格', '未分组', '中国风动画，优雅空灵的美学，流畅动感的线条，柔和发光的奇幻光影，浓郁的东方色彩调色盘，精致奢华的细节。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c112374af656473b8cb536.jpg', 'style-library/public/826515925972398083/cover.jpg', '/api/style-library/images/826515925972398083', 2752, 1536, true, 111, now(), now()),
  ('826515887326083061', '水墨漫画风格', '未分组', '传统中国水墨画，单色配以朱砂红点缀，富有表现力的笔触，写意水墨风格，艺术性留白，传统宣纸纹理。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1126f4af656473b8cb53f.jpg', 'style-library/public/826515887326083061/cover.jpg', '/api/style-library/images/826515887326083061', 2752, 1536, true, 112, now(), now()),
  ('826515846481950699', '新中式漫画风格', '未分组', '新中式美学，现代平涂结合传统东方元素，翡翠绿与金箔配色，流畅的东方设计感，现代水墨风格。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1128a4af656473b8cb547.jpg', 'style-library/public/826515846481950699/cover.jpg', '/api/style-library/images/826515846481950699', 2752, 1536, true, 113, now(), now()),
  ('826515729880299473', '复古漫画风格', '未分组', '复古漫画书风格，半色调网点图案，胶印效果，褪色复古色彩，泛黄的纸张纹理，复古波普艺术美学，粗犷轮廓线。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c112a3cad46a443b2b07ee.jpg', 'style-library/public/826515729880299473/cover.jpg', '/api/style-library/images/826515729880299473', 2752, 1536, true, 114, now(), now()),
