  ('826515456864663456', '蒸汽波漫风格', '未分组', '蒸汽波美学，复古未来主义，霓虹粉色与紫色的渐变，怀旧VHS滤镜，微妙的故障艺术，超现实主义基调，80年代合成器波氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c113264af656473b8cb55e.jpg', 'style-library/public/826515456864663456/cover.jpg', '/api/style-library/images/826515456864663456', 2752, 1536, true, 120, now(), now()),
  ('826515105495234403', '平涂简约风格', '未分组', '极简主义插画，超平涂阴影，几何形状语言，克制但醒目的配色，干净的矢量线条，高视觉冲击力，巧妙的留白。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1135c4af656473b8cb566.jpg', 'style-library/public/826515105495234403/cover.jpg', '/api/style-library/images/826515105495234403', 2752, 1536, true, 121, now(), now()),
  ('826515058963625822', '电影感悬疑风格', '未分组', '电影级静帧，35毫米镜头，大片质感，好莱坞级色彩分级，高对比度低调照明，冷硬派色调，阿莱阿莱克萨摄影机拍摄，戏剧性阴影，充满故事感的压抑氛围，极具张力的景深。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1137a4af656473b8cb572.jpg', 'style-library/public/826515058963625822/cover.jpg', '/api/style-library/images/826515058963625822', 2752, 1536, true, 122, now(), now()),
  ('826515000721520389', '商业影视风格', '未分组', '高端商业摄影，韩剧质感，柔和且充满光泽感的高光，干净剔透的画面，棚拍级主光与轮廓光，高级冷艳色调，奢华质感，极高的清晰度，8k分辨率，画面极具质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1138fcad46a443b2b081e.jpg', 'style-library/public/826515000721520389/cover.jpg', '/api/style-library/images/826515000721520389', 2752, 1536, true, 123, now(), now()),
  ('826514960145823484', '日系胶片风格', '未分组', '富士自然彩色胶片质感，边缘漏光效果，柔和自然的阳光，低对比度，强烈的空气感，微弱的胶片颗粒，日系小清新摄影，温柔治愈的低饱和色调，唯美自然景深。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c113c44af656473b8cb57c.jpg', 'style-library/public/826514960145823484/cover.jpg', '/api/style-library/images/826514960145823484', 2752, 1536, true, 124, now(), now()),
  ('826514917137430256', '中式古风', '未分组', '东方古典影视美学，电影级古装剧布光，丁达尔效应（耶各射线），朦胧的雾气弥漫，冷暖光交替，极具东方意境的打光，电影宽银幕比例，精美华丽的质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c113db4af656473b8cb57e.jpg', 'style-library/public/826514917137430256/cover.jpg', '/api/style-library/images/826514917137430256', 2752, 1536, true, 125, now(), now()),
  ('826514869267838698', '末日科幻风格', '未分组', '废土美学，末日科幻电影质感，灰暗低饱和度调色，强烈的颗粒感与脏污纹理，冷酷的环境光渲染，史诗级电影画面，高锐度，废土朋克氛围。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c113eb4af656473b8cb583.jpg', 'style-library/public/826514869267838698/cover.jpg', '/api/style-library/images/826514869267838698', 2752, 1536, true, 126, now(), now()),
  ('826514832714479334', '年代剧风格', '未分组', '中国80年代复古质感，微泛黄的暖色调，怀旧的时代氛围，柔和的颗粒感，充满年代感的布光。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1141d4af656473b8cb58c.jpg', 'style-library/public/826514832714479334/cover.jpg', '/api/style-library/images/826514832714479334', 2752, 1536, true, 127, now(), now()),
  ('826514727177402068', '邵氏武侠风格', '未分组', '武侠电影风格( 1960s-1980s)，摄影棚搭景/室内片场感，非自然主义光影，邵氏综摄宽银幕构图，人工布光、戏剧性主光，特艺彩色取向，老胶片成像质感。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69c1142a4af656473b8cb595.jpg', 'style-library/public/826514727177402068/cover.jpg', '/api/style-library/images/826514727177402068', 2752, 1536, true, 128, now(), now()),
  ('796401448849278038', '漫剧风格-美式动画', '漫剧风格', '美式动画风格，线条粗犷流畅，色彩饱和明亮，阴影对比强烈。造型夸张变形，动作幅度大且富有弹性。常用平涂上色，轮廓线清晰。节奏明快，充满戏剧张力，视觉冲击力强，带有漫画感和pop art特质。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/6953825c189606bfcc5a2ff5.jpeg', 'style-library/public/796401448849278038/cover.jpg', '/api/style-library/images/796401448849278038', 2048, 1152, true, 129, now(), now()),
  ('796401368238949452', '漫剧风格-末世废土风', '漫剧风格', 'Max Bedulenko 废土科幻概念艺术，粗糙的拼接质感，细腻的沙尘纹理，电影感构图，数字绘画，高细节，8K。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/695380b0189606bfcc5a2fa7.jpeg', 'style-library/public/796401368238949452/cover.jpg', '/api/style-library/images/796401368238949452', 2048, 1152, true, 130, now(), now()),
  ('796391532700927312', '漫剧风格-赛博朋克', '漫剧风格', '赛博朋克风格，霓虹光效璀璨，色调冷峻深沉，以蓝紫粉为主色，科技感强烈，画面层次复杂，营造未来都市的迷幻与颓废气质。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/69537861189606bfcc5a2e2a.jpeg', 'style-library/public/796391532700927312/cover.jpg', '/api/style-library/images/796391532700927312', 2048, 1152, true, 131, now(), now()),
  ('796391465348788873', '漫剧风格-皮克斯动画', '漫剧风格', '皮克斯动画风格，色彩饱满鲜艳，造型圆润流畅，材质表现精致，光影效果真实，画面充满活力与趣味，技术与艺术完美融合的现代风格。', 'https://zy-dimnx.oss-cn-shenzhen.aliyuncs.com/uploads/768773509097758853/style/image/695377b5189606bfcc5a2df8.jpeg', 'style-library/public/796391465348788873/cover.jpg', '/api/style-library/images/796391465348788873', 2048, 1152, true, 132, now(), now()),
